    const d=det[i], ad=d<0?-d:d, g=Em[i]/(Em[i]+k2s2); // smooth Wiener-style gate
    let v=Y[i]+d*g*boost;
    // Overshoot allowance distinguishes texture from halos: at fine texture
    // the pixel's own detail is comparable to the whole window range (2|d| ≈
    // mx−mn) so boosting past the old extreme is legitimate; at a halo pixel
    // the window range is dominated by a nearby EDGE (|d| ≪ mx−mn), so the
    // clamp stays tight and ringing remains impossible.
    const rng=(mx[i]-mn[i])+2*ad, texQ=rng>0?Math.min(1,(ad+ad)/rng):1;
    const ov=rng*0.12+0.8*scale+ad*g*boost*texQ;
