  mask:null, mw:0, mh:0, maskView:'overlay',
  bg:'#ffffff', bgBlur:8, bgMode:'color',
  layer:'subject',
  salThresh:50, edgeStrength:50, edgeDetail:55, edgeSensitivity:50, bgStrength:35, focusPts:[], region:null, tab:'quick',
  brushMask:null, brushW:0, brushH:0, brushOn:false, brushSize:42, dragging:false,
  // Hand-edit pins for the mask Erase/Add brush: pixels the user painted that
  // the edge-refine must leave verbatim (see pinReset/pinFromDiff).
  maskPin:null, _pinCount:0, _pinIdx:null,
  // Tone curve: control points per channel in 0..255 space. Empty/identity = [[0,0],[255,255]].
