  curveChan:'rgb',
  // HSL mixer: 8 hue bands, each {h,s,l} shift in -100..100.
  hsl:{ _basis:'oklab', red:{h:0,s:0,l:0}, orange:{h:0,s:0,l:0}, yellow:{h:0,s:0,l:0}, green:{h:0,s:0,l:0}, aqua:{h:0,s:0,l:0}, blue:{h:0,s:0,l:0}, purple:{h:0,s:0,l:0}, magenta:{h:0,s:0,l:0} },
  hslBand:'red',
  exif:null,
  lensAutoApplied:false,
  // Offline Lens Profiles (Lensfun subset). lensProfile holds the resolved
  // calibration coefficients ({dist,vig,tca}) for the matched/selected lens;
  // lensProfileIdx indexes LENSFUN_DB; lensCorrect gates the calibrated passes;
