      gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D,texMask);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.R8,mw,mh,0,gl.RED,gl.UNSIGNED_BYTE,mask);
