/* Four-corner edit lives in a contained preview instead of intercepting
   taps on the main photo. The committed normalised corners feed the SAME
   inverse mapping used by scene-linear RAW preview and full-size export. */
const NijQuad=(()=>{
  const rect=()=>[[0,0],[1,0],[1,1],[0,1]];
  let points=rect(),drag=-1;
  const $id=id=>document.getElementById(id);
  function paint(){
    const poly=$id('nijQuadPolygon');if(!poly)return;
    poly.setAttribute('points',points.map(p=>Math.round(p[0]*1000)+','+Math.round(p[1]*1000)).join(' '));
    $id('nijQuadLayer')?.querySelectorAll('[data-nij-corner]').forEach(b=>{
      const p=points[Number(b.dataset.nijCorner)];
      b.style.left=Math.max(4,Math.min(96,p[0]*100))+'%';
      b.style.top=Math.max(4,Math.min(96,p[1]*100))+'%';
    });
  }
  function size(){
    const src=S.proxy,canvas=$id('nijQuadCanvas'),image=$id('nijQuadImage');
    if(!src||!canvas||!image)return;
    const scale=Math.min(1,Math.max(160,Math.min(540,window.innerWidth-64))/src.width,
      Math.max(140,Math.min(window.innerHeight*.60,window.innerHeight-190))/src.height);
    const w=Math.max(1,Math.round(src.width*scale)),h=Math.max(1,Math.round(src.height*scale));
    canvas.style.width=image.style.width=w+'px';canvas.style.height=image.style.height=h+'px';
  }
  function open(){
    if(!S.proxy){toast('Open a photo first');return;}
    const dlg=$id('nijQuadDialog'),canvas=$id('nijQuadCanvas');if(!dlg||!canvas)return;
    canvas.width=S.proxy.width;canvas.height=S.proxy.height;
    canvas.getContext('2d').putImageData(S.proxy,0,0);
    points=nijQuadValid(S.perspectiveQuad)?S.perspectiveQuad.map(p=>p.slice()):rect();
    size();paint();dlg.showModal();
  }
  function close(){drag=-1;$id('nijQuadDialog')?.close();}
  function reset(){points=rect();paint();}
  function set(i,x,y){
    // Confine each corner to its own quadrant: no self-intersecting or
    // near-singular homography can be committed by touch or keyboard.
    const left=i===0||i===3,top=i<2;
    x=Math.max(left?0:.54,Math.min(left?.46:1,x));
    y=Math.max(top?0:.54,Math.min(top?.46:1,y));
    const next=points.map(p=>p.slice());next[i]=[x,y];
    if(nijQuadValid(next)){points=next;paint();}
  }
  function apply(){
    if(!S.proxy||!nijQuadValid(points)){toast('Choose four valid corners');return;}
    const normal=rect().every((p,i)=>Math.abs(p[0]-points[i][0])+Math.abs(p[1]-points[i][1])<1e-5);
    S.perspectiveQuad=normal?null:points.map(p=>p.slice());
    P.perspH=P.perspV=0;syncSliders();nijMarkCornerMode();close();render();commit();
    if(typeof nijQueueGeometryThumbs==='function')nijQueueGeometryThumbs();
    toast(normal?'Perspective reset':'Four-corner perspective applied with safe crop');
  }
  document.addEventListener('pointerdown',e=>{
    const b=e.target.closest?.('#nijQuadLayer [data-nij-corner]');if(!b)return;
    drag=Number(b.dataset.nijCorner);b.setPointerCapture(e.pointerId);e.preventDefault();
  });
  document.addEventListener('pointermove',e=>{
    if(drag<0)return;
    const box=$id('nijQuadLayer')?.getBoundingClientRect();if(!box?.width||!box.height)return;
    set(drag,(e.clientX-box.left)/box.width,(e.clientY-box.top)/box.height);
    e.preventDefault();
  });
  document.addEventListener('pointerup',()=>{drag=-1;});
  document.addEventListener('pointercancel',()=>{drag=-1;});
  document.addEventListener('keydown',e=>{
    const b=e.target.closest?.('#nijQuadLayer [data-nij-corner]');if(!b)return;
    const dx=e.key==='ArrowRight'?.01:e.key==='ArrowLeft'?-.01:0;
    const dy=e.key==='ArrowDown'?.01:e.key==='ArrowUp'?-.01:0;
    if(!dx&&!dy)return;
    const i=Number(b.dataset.nijCorner);set(i,points[i][0]+dx,points[i][1]+dy);e.preventDefault();
  });
  window.addEventListener('resize',()=>{if($id('nijQuadDialog')?.open)size();});
  return {open,close,reset,apply};
})();
function nijMarkCornerMode(){
  document.querySelectorAll('[data-nij-corners]').forEach(b=>{
    const active=!!S.perspectiveQuad;
    b.classList.toggle('on',active);
    b.setAttribute('aria-pressed',String(active));
    b.textContent=active?'Four corners · active':'Four corners…';
  });
}
function nijResetPerspective(){
  if(!S.proxy){toast('Open a photo first');return;}
  S.perspectiveQuad=null;P.perspV=P.perspH=0;syncSliders();nijMarkCornerMode();render();commit();
  toast('Perspective reset');
}
