        if(x0<0)x0=0; if(x1>mw-1)x1=mw-1; if(x0>mw-1)x0=mw-1;
        const a=mask[y0*mw+x0], b=mask[y0*mw+x1], c=mask[y1*mw+x0], e=mask[y1*mw+x1];
