  //    (on handle drags) stays consistent with the swapped alpha.
  if(typeof GeoMask!=='undefined'){ const g=GeoMask.get(); if(g){ g.invert=!g.invert; GeoMask.set(g); if(typeof renderGeoHandles==='function')renderGeoHandles(); if(typeof updateGeoUI==='function')updateGeoUI(); } }
  // 3. Swap the per-layer adjustment objects so edits follow their region.
  const tmp=S.L.subject; S.L.subject=S.L.background; S.L.background=tmp;
  // background carries an extra 'blur' key; subject has none — keep blur on bg.
  if(S.L.subject.blur!==undefined){ if(S.L.background.blur===undefined) S.L.background.blur=S.L.subject.blur; delete S.L.subject.blur; }
  if(S.L.background.blur===undefined) S.L.background.blur=0;
