  S.brushMask=null; S.brushW=0; S.brushH=0; S.brushOn=false; const _bst=$('#stage'); if(_bst)_bst.classList.remove('brushing'); const _bov=$('#brushov'); if(_bov)_bov.style.display='none';
  S.maskEraseOn=false; const _mest=$('#stage'); if(_mest)_mest.classList.remove('merase'); const _meo=$('#maskerov'); if(_meo)_meo.style.display='none'; updateMaskEraseUI();
