  dc.style.display='block';
  if(innerWidth<=980&&typeof snap==='function'&&!(typeof sheetIsSideDock==='function'&&sheetIsSideDock()))snap(0.43);
  { const zc=$('#zoomctl'); if(zc)zc.classList.add('show'); if(typeof resetCvView==='function') resetCvView(); }
  ['btnAuto','btnReset','btnExport','btnCrop','btnRotate','btnDenoise','btnSplit','btnHold','btnHistPick','btnHistory','btnSaveEdits','btnTwoLooks'].forEach(id=>{ const el=$('#'+id); if(el)el.disabled=false; });
  if(typeof updateCopyPasteUI==='function') updateCopyPasteUI();
