    +'<div class="row"><label>Hue</label><input type="range" aria-label="Red hue" class="hsl-sl" data-hsl="h" min="-100" max="100" step="1" value="0"><span class="v" data-hsl-v="h">0</span>'+nijLessonHTML('hslHue')+'</div>'
    +'<div class="row"><label>Saturation</label><input type="range" aria-label="Red saturation" class="hsl-sl" data-hsl="s" min="-100" max="100" step="1" value="0"><span class="v" data-hsl-v="s">0</span>'+nijLessonHTML('hslSaturation')+'</div>'
    +'<div class="row"><label>Luminance</label><input type="range" aria-label="Red luminance" class="hsl-sl" data-hsl="l" min="-100" max="100" step="1" value="0"><span class="v" data-hsl-v="l">0</span>'+nijLessonHTML('hslLuminance')+'</div>'
    +'<div class="curve-foot" style="margin-top:4px;gap:7px;flex-wrap:wrap"><span class="ch-hint" data-hsl-active>Editing RED</span><button type="button" class="ch-reset" data-hsl-pick onclick="toggleHSLPick()" title="Tap a color in the photograph to choose its mixer band">Pick from photo</button><button type="button" class="ch-reset" onclick="resetHSLband()">Reset band</button></div>'
    +'</div>';
