    +'</div>'
    +'<div style="display:flex;gap:8px;align-items:center;margin-top:8px"><label class="hint" data-nij-kelvin-label style="min-width:88px">'+info.label+'</label>'
    +'<input data-nij-kelvin type="number" min="2000" max="25000" step="50" placeholder="As shot" value="'+nijKelvinDisplayValue()+'" '
    +'style="width:100%;min-height:38px;padding:0 9px;background:var(--card);border:1px solid var(--line2);border-radius:7px" '
    +'aria-label="Colour temperature; approximate for RAW, relative for rendered images" onchange="nijSetKelvin(this)"></div>'
    +'<p class="hint" data-nij-kelvin-note style="margin:5px 0 0;font-size:.7rem">'+info.note+'</p>';
