/* NijRAW uses only coefficients from its bundled, attributed upstream
   Lensfun XML database. This build contains no hand-authored lens profiles,
   no lens-family correction guesses and no untrusted XML imports.
   Calibration is community-contributed, not independently bench-verified by
   NijRAW. Manual distortion/vignetting sliders are not lens calibrations. */

/* The complete upstream XML database is converted into this embedded JSON
   snapshot at build time. Only models with implemented formulas are included.
   No runtime download or account is needed. The *database adaptation* remains
   CC BY-SA 3.0, credited in the adjacent HTML data block and Lens panel.
   Saved projects are matched by maker/model, never by historical numeric index. */
const LENSFUN_FULL_DB=(()=>{
  try{
    const el=document.getElementById('nijraw-lensfun-bundle');
    const data=JSON.parse(el?.textContent||'{}');
    if(!Array.isArray(data.lenses)||!Array.isArray(data.cameras))throw Error('Invalid database structure');
    return data;
  }catch(e){console.warn('Offline Lensfun bundle unavailable',e);return {lenses:[],cameras:[]};}
})();
const LENSFUN_DB=LENSFUN_FULL_DB.lenses.filter(r=>r.source==='lensfun' &&
  (r.dist?.length||r.vig?.length||r.tca?.length));
const LENSFUN_BUILTIN_COUNT=LENSFUN_DB.length;

/* Build the maker → [lens] index from upstream records only. */
const LENS_PROFILES = (function(){
  const out={};
  LENSFUN_DB.forEach((L,i)=>{ (out[L.maker]=out[L.maker]||[]).push({idx:i, name:L.model}); });
  for(const models of Object.values(out))models.sort((a,b)=>a.name.localeCompare(b.name));
  return out;
})();

/* ── Resolve a DB record + shot conditions into flat correction coefficients ──
   Given a lens record and the EXIF focal length / aperture (either may be
   null), interpolate the per-focal (and per-aperture) calibration rows into a
   single resolved profile the pixel passes consume. Missing defects resolve to
   null so the corresponding pass is skipped. */
function resolveLensProfile(rec, focal, aperture){
  const near=(rows,key,val)=>{
    // Nearest / linear interpolation over `rows` by `rows[i][key]`. Falls back
    // to the single available row when val is unknown or the list is length 1.
    if(!rows||!rows.length) return null;
    if(rows.length===1||val==null) return rows[Math.max(0,Math.floor(rows.length/2)>rows.length-1?0:0)]&&rows[0];
    let lo=rows[0], hi=rows[rows.length-1];
    if(val<=lo[key]) return lo;
    if(val>=hi[key]) return hi;
    for(let i=0;i<rows.length-1;i++){
      const a=rows[i], b=rows[i+1];
      if(val>=a[key] && val<=b[key]){
        const t=(b[key]-a[key])? (val-a[key])/(b[key]-a[key]) : 0;
        const o={}; for(const kk in a){ o[kk]=(typeof a[kk]==='number'&&typeof b[kk]==='number')? a[kk]+(b[kk]-a[kk])*t : a[kk]; }
        return o;
      }
    }
    return lo;
  };
  const res={ maker:rec.maker, model:rec.model, source:'lensfun',
              datasetKey:[rec.maker,rec.model,rec.mount,rec.crop].join('|'),
              focal:focal, aperture:aperture,
              dist:null, vig:null, tca:null };
  // Distortion: interpolate on focal.
  const d=near(rec.dist,'f',focal);
  if(d) res.dist={ m:d.m||'poly3', k1:d.k1||0, k2:d.k2||0,
    a:d.a||0, b:d.b||0, c:d.c||0 };
  // Vignetting: pick focal-nearest subset first, then interpolate on aperture.
  if(rec.vig && rec.vig.length){
    let rows=rec.vig;
    if(focal!=null){
      // narrow to rows whose focal is closest to the shot focal
      let bestF=null, bestD=Infinity;
      rows.forEach(r=>{ const dd=Math.abs(r.f-focal); if(dd<bestD){bestD=dd;bestF=r.f;} });
      const sub=rows.filter(r=>r.f===bestF);
      if(sub.length) rows=sub;
    }
    rows=rows.slice().sort((a,b)=>a.a-b.a);
    const v=near(rows,'a',aperture);
    if(v) res.vig={ k1:v.k1||0, k2:v.k2||0, k3:v.k3||0 };
  }
  // TCA: interpolate on focal.
  const t=near(rec.tca,'f',focal);
  if(t) res.tca={ br:t.br||0, cr:t.cr||0, vr:t.vr!=null?t.vr:1,
    bb:t.bb||0, cb:t.cb||0, vb:t.vb!=null?t.vb:1 };
  return res;
}

/* ── Calibrated pixel passes ─────────────────────────────────────────────────
   These consume S.lensProfile (the resolved coefficients) and run in addition
   to the manual sliders. Each is a strict no-op when its coefficient block is
   absent or the master amount is 0, so an image with no matched lens is
   byte-for-byte unchanged. `amt` (0..1) scales every calibrated correction so
   the user can dial the whole profile up or down. */
/* Re-resolve every saved/imported/history profile against the bundled upstream
   coefficients. Serialized numeric IDs are not trusted, and old heuristic or
   user-imported coefficients are never allowed to reach the renderer. */
const _nijTrustedLensObjects=new WeakSet();
const _nijLensByDataKey=new Map();
const _nijLensByModel=new Map();
LENSFUN_DB.forEach((r,i)=>{
  _nijLensByDataKey.set([r.maker,r.model,r.mount,r.crop].join('|'),i);
  const k=r.maker+'|'+r.model;
  const found=_nijLensByModel.get(k)||[];found.push(i);_nijLensByModel.set(k,found);
});
function nijVerifyLensSelection(){
  if(typeof S==='undefined'||!S.lensProfile)return false;
  const p=S.lensProfile;
  if(_nijTrustedLensObjects.has(p))return true;
  let idx=-1;
  if(p.source==='lensfun'&&typeof p.maker==='string'&&typeof p.model==='string'){
    if(typeof p.datasetKey==='string'&&_nijLensByDataKey.has(p.datasetKey)){
      const candidate=_nijLensByDataKey.get(p.datasetKey);
      if(LENSFUN_DB[candidate].maker===p.maker&&LENSFUN_DB[candidate].model===p.model)
        idx=candidate;
    }
    else if(!p.datasetKey){
      const matches=_nijLensByModel.get(p.maker+'|'+p.model)||[];
      if(matches.length===1)idx=matches[0];
    }
  }
  if(idx<0){
    S.lensProfile=null;S.lensProfileIdx=null;S.lensCorrect=false;
    return false;
  }
  const rec=LENSFUN_DB[idx];
  const focal=Number.isFinite(p.focal)?p.focal:null;
  const aperture=Number.isFinite(p.aperture)?p.aperture:null;
  const clean=resolveLensProfile(rec,focal,aperture);
  S.lensProfile=clean;S.lensProfileIdx=idx;
  _nijTrustedLensObjects.add(clean);
  return true;
}
function lensfunActive(){
  return nijVerifyLensSelection() && S.lensCorrect &&
         (S.lensCorrectAmt==null || S.lensCorrectAmt>0);
}
/* Distortion: only the upstream Lensfun/Hugin poly3, poly5 and PTLens models.
   r=1 is the half of the shorter image side. The separate PA vignetting model
   below correctly uses r=1 at the image corner. */
function nijLensfunRadialFactor(dist,ru,amt){
  const m=dist.m,k1=(dist.k1||0)*amt,k2=(dist.k2||0)*amt;
  if(m==='ptlens'){
    const a=(dist.a||0)*amt,b=(dist.b||0)*amt,c=(dist.c||0)*amt;
    const d=1-a-b-c;
    // Mirror upstream Lensfun's focal-length-preserving PTLens conversion:
    // a'=a/d^4, b'=b/d^3, c'=c/d^2, constant'=1.
    if(d<0.1)return 1;
    return 1+(a/(d*d*d*d))*ru*ru*ru+(b/(d*d*d))*ru*ru+(c/(d*d))*ru;
  }
  if(m==='poly5')return 1+k1*ru*ru+k2*ru*ru*ru*ru;
  const d=1-k1;
  return d>0.1?1+(k1/(d*d*d))*ru*ru:1;
}
function lensfunDistortApply(d,w,h){
  const P0=S.lensProfile; if(!P0||!P0.dist) return d;
  const amt=(S.lensCorrectAmt==null?100:S.lensCorrectAmt)/100;
  if(amt<=0) return d;
  const D=P0.dist;
  if(!(D.k1||D.k2||D.a||D.b||D.c))return d;
  const cx=(w-1)/2, cy=(h-1)/2;
  const norm=Math.min(cx,cy)||1;
  const rd=(ru)=>ru*nijLensfunRadialFactor(D,ru,amt);
  // Auto-scale: solve for S so the corner (Ru=1) maps back onto the source edge
  // when the model pulls samples inward (barrel). If rd(1) < 1 we'd leave gaps,
  // so scale up by 1/rd(1); clamp so we never zoom for pincushion.
  let S1 = rd(1);
  let scale = (S1>0 && S1<1) ? 1/S1 : 1;
  const out=new Uint8ClampedArray(d.length);
  const pix=[0,0,0],wx=new Float64Array(4),wy=new Float64Array(4),lut=skLinearLUT(255);
  for(let y=0;y<h;y++){
    for(let x=0;x<w;x++){
      let nx=(x-cx)/norm, ny=(y-cy)/norm;
      const ru=Math.sqrt(nx*nx+ny*ny)*scale;
      const f = ru>1e-8 ? rd(ru)/ru : 1;
      let sx=cx+nx*scale*f*norm, sy=cy+ny*scale*f*norm;
      if(sx<0)sx=0; else if(sx>w-1.001)sx=w-1.001;
      if(sy<0)sy=0; else if(sy>h-1.001)sy=h-1.001;
      const o=(y*w+x)*4;
      skSampleCubic(d,w,h,4,255,sx,sy,pix,lut,wx,wy);
      out[o]=pix[0];out[o+1]=pix[1];out[o+2]=pix[2];
      out[o+3]=255;
    }
  }
  return out;
}
/* Vignetting: Lensfun "pa" model. The measured corner fall-off is
   V(r) = 1 + k1·r² + k2·r⁴ + k3·r⁶ (V<1 toward the corners); correction
   multiplies each pixel by 1/V to lift the darkened periphery back up. amt
   blends between no correction (1) and full (1/V). In-place. */
function lensfunVignApply(d,w,h){
  const P0=S.lensProfile; if(!P0||!P0.vig) return;
  const amt=(S.lensCorrectAmt==null?100:S.lensCorrectAmt)/100;
  if(amt<=0) return;
  const {k1,k2,k3}=P0.vig;
  if(k1===0&&k2===0&&k3===0) return;
  const cx=(w-1)/2, cy=(h-1)/2, norm=cx*cx+cy*cy||1,lut=skLinearLUT(255);
  for(let y=0;y<h;y++){
    for(let x=0;x<w;x++){
      const dx=x-cx, dy=y-cy, r2=(dx*dx+dy*dy)/norm;
      const r4=r2*r2, r6=r4*r2;
      let V=1 + k1*r2 + k2*r4 + k3*r6;
      if(V<0.05) V=0.05;                 // guard against blow-ups near a bad fit
      const gain=1 + (1/V - 1)*amt;
      const p=(y*w+x)*4;
      d[p]=Math.round(skToSrgb(skClamp(lut[d[p]]*gain))*255);
      d[p+1]=Math.round(skToSrgb(skClamp(lut[d[p+1]]*gain))*255);
      d[p+2]=Math.round(skToSrgb(skClamp(lut[d[p+2]]*gain))*255);
    }
  }
}
/* Transverse chromatic aberration: full Lensfun/Hugin poly3 / linear TCA.
   Unlike PA vignetting, the Hugin coordinate radius is normalised to the
   shorter image half-side; the linear-r terms cr/cb are also supported. */
function lensfunTCAApply(d,w,h){
  const P0=S.lensProfile; if(!P0||!P0.tca) return d;
  const amt=(S.lensCorrectAmt==null?100:S.lensCorrectAmt)/100;
  if(amt<=0) return d;
  let {br,vr,bb,vb}=P0.tca;
  const cr=P0.tca.cr||0,cb=P0.tca.cb||0;
  // Blend each channel's scale toward identity (1) by amt.
  const sR=(r)=> 1 + ((vr-1) + cr*r + br*r*r)*amt;
  const sB=(r)=> 1 + ((vb-1) + cb*r + bb*r*r)*amt;
  if(Math.abs(vr-1)<1e-7 && Math.abs(br)<1e-9 && Math.abs(cr)<1e-9 &&
    Math.abs(vb-1)<1e-7 && Math.abs(bb)<1e-9 && Math.abs(cb)<1e-9) return d;
  const cx=(w-1)/2, cy=(h-1)/2;
  const norm=Math.min(cx,cy)||1;
  const out=new Uint8ClampedArray(d);
  const lut=skLinearLUT(255),wx=new Float64Array(4),wy=new Float64Array(4);
  const sample=(sx,sy,c)=>{
    return skSampleCubicChannel(d,w,h,4,255,sx,sy,c,lut,wx,wy);
  };
  for(let y=0;y<h;y++){
    const dy=y-cy;
    for(let x=0;x<w;x++){
      const dx=x-cx, r=Math.hypot(dx,dy)/norm;
      const fr=sR(r), fb=sB(r);
      const o=(y*w+x)*4;
      out[o]  =sample(cx+dx*fr, cy+dy*fr, 0);  // red plane
      out[o+2]=sample(cx+dx*fb, cy+dy*fb, 2);  // blue plane
      // green (o+1) and alpha (o+3) unchanged
    }
  }
  return out;
}

function lensProfileHTML(){
  const makeOpts=Object.keys(LENS_PROFILES).map(m=>'<option value="'+esc(m)+'">'+esc(m)+'</option>').join('');
  const measuredDist=LENSFUN_DB.filter(r=>r.dist&&r.dist.length).length;
  const measuredVig=LENSFUN_DB.filter(r=>r.vig&&r.vig.length).length;
  const measuredTCA=LENSFUN_DB.filter(r=>r.tca&&r.tca.length).length;
  return '<div class="lens-profile" data-lensprofile style="margin-bottom:12px;padding:10px 11px;border:1px solid var(--line2);border-radius:11px;background:var(--paper2)">'
    +'<div class="epop-row" style="margin-bottom:8px"><label>Lens make</label><select data-lensmake onchange="onLensMakeChange(this)"><option value="">Select…</option>'+makeOpts+'</select></div>'
    +'<div class="epop-row" style="margin-bottom:8px"><label>Lens model</label><select data-lensmodel onchange="applyLensProfile(this)" disabled><option value="">Select a make first</option></select></div>'
    +'<p class="hint" style="margin:0 0 8px;font-size:.64rem">Built in offline: '+LENSFUN_BUILTIN_COUNT+' upstream Lensfun records, with '+measuredDist+' distortion, '+measuredVig+' vignetting, and '+measuredTCA+' chromatic calibrations. Data adapted from <a target="_blank" rel="noopener noreferrer" href="https://github.com/lensfun/lensfun/tree/master/data/db">Lensfun</a> © contributors, <a target="_blank" rel="noopener noreferrer" href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>. No invented presets, family-based estimates or unchecked XML imports are included. Source provenance is verified; individual optical measurements have not been independently tested by NijRAW. High-confidence EXIF matches are selected but never enabled automatically. Camera-embedded optical opcodes are not decoded.</p>'
    +'<div data-lenscalib style="display:none;flex-direction:column;gap:8px;margin-top:2px">'
      +'<div style="display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:8px 9px;border:1px solid var(--line2);border-radius:9px;background:var(--paper)"><span data-lensactive style="font-size:.7rem;flex:1;min-width:140px">Corrections off · GPU preview remains available</span><button type="button" class="tl" data-lensapplybtn onclick="setLensCorrectionEnabled()" aria-pressed="false" style="width:auto;flex:0 0 auto;padding:0 11px">Apply when finished</button></div>'
      +'<div style="display:flex;flex-wrap:wrap;gap:6px" data-lenstoggles>'
        +'<button type="button" class="tl lens-tg on" data-lensdefect="dist" onclick="toggleLensDefect(\'dist\')" style="width:auto;padding:0 10px;flex:0 0 auto">Distortion</button>'
        +'<button type="button" class="tl lens-tg on" data-lensdefect="vig" onclick="toggleLensDefect(\'vig\')" style="width:auto;padding:0 10px;flex:0 0 auto">Vignetting</button>'
        +'<button type="button" class="tl lens-tg on" data-lensdefect="tca" onclick="toggleLensDefect(\'tca\')" style="width:auto;padding:0 10px;flex:0 0 auto">Chromatic</button>'
      +'</div>'
      +'<div class="row" style="margin:0"><label>Amount</label><input type="range" data-lensamt min="0" max="100" step="1" value="100" oninput="setLensCorrectAmt(this.value)"><span class="v" data-lensamtv>100</span><p class="nij-slider-lesson">Controls how much of the selected lens profile is applied; lower it if the correction looks unnatural.</p></div>'
      +'<p class="hint" data-lenscalibnote style="margin:0;font-size:.66rem"></p>'
      +'<p class="hint" style="margin:0;font-size:.65rem">Finishing step: enabling Lensfun correction may use the slower CPU preview. Apply it after other edits; exports include it only when enabled.</p>'
    +'</div>'
    +'<p class="hint" data-lensdetect style="margin:8px 0 0;font-size:.68rem;display:none"></p>'
    +'</div>';
}
function onLensMakeChange(sel){
  const wrap=sel.closest('[data-lensprofile]'); if(!wrap) return;
  const modelSel=wrap.querySelector('[data-lensmodel]');
  const found=Object.prototype.hasOwnProperty.call(LENS_PROFILES,sel.value)?LENS_PROFILES[sel.value]:null;
  const list=Array.isArray(found)?found:[];
  modelSel.innerHTML='<option value="">Select…</option>'+list.map(l=>'<option value="'+(Number.isSafeInteger(l.idx)?l.idx:0)+'">'+esc(l.name)+' · Lensfun</option>').join('');
  modelSel.disabled=!sel.value;
}
/* Manual model pick selects a verified calibration without enabling it. This
   keeps the responsive GPU preview throughout editing; the separate Apply
   button is the explicit finishing step. */
function applyLensProfile(sel){
  const wrap=sel.closest('[data-lensprofile]'); if(!wrap) return;
  if(sel.value==='') return;
  const rec=LENSFUN_DB[+sel.value]; if(!rec) return;
  const ex=(typeof S!=='undefined')?S.exif:null;
  const focal=ex&&ex.focalV!=null?ex.focalV:(ex&&ex.focal!=null?ex.focal:null);
  const aperture=ex&&ex.aperture!=null?ex.aperture:null;
  S.lensProfile=resolveLensProfile(rec,focal,aperture);
  S.lensProfileIdx=+sel.value;
  S.lensCorrect=false;
  S.lensAutoApplied=true;
  if(S.lensCorrectAmt==null) S.lensCorrectAmt=100;
  if(!S.lensDefects) S.lensDefects={dist:true,vig:true,tca:true};
  syncLensPanel();
  render(); commit();
  if(typeof toast==='function') toast('Lens profile ready: '+rec.maker+' '+rec.model+'. Apply corrections when finished editing.');
}
function setLensCorrectionEnabled(force){
  if(!nijVerifyLensSelection()||!S.lensProfile){
    if(typeof toast==='function')toast('Select a verified Lensfun profile first.');
    return;
  }
  const enabled=typeof force==='boolean'?force:!S.lensCorrect;
  if(S.lensCorrect===enabled)return;
  if(enabled&&!(S.lensCorrectAmt>0))S.lensCorrectAmt=100;
  S.lensCorrect=enabled;S.lensAutoApplied=true;
  syncLensPanel();render();commit();
  if(typeof toast==='function')toast(enabled?
    'Lens correction applied. RAW preview may use the CPU; export keeps these corrections.':
    'Lens correction turned off. GPU preview can run while you continue editing.');
}
function toggleLensDefect(which){
  if(!S.lensDefects) S.lensDefects={dist:true,vig:true,tca:true};
  S.lensDefects[which]=!S.lensDefects[which];
  syncLensPanel();
  render(); commit();
}
function setLensCorrectAmt(v){
  S.lensCorrectAmt=+v;
  $$('[data-lensamtv]').forEach(el=>el.textContent=Math.round(+v));
  $$('[data-lensamt]').forEach(el=>{ if(el.value!=v) el.value=v; });
  S.dragging=true; render();
}
/* Reflect S.lensProfile / toggles / amount into every mounted panel. Keeps the
   pickers, defect buttons, amount slider and calibration note in sync after any
   programmatic change (EXIF auto-apply, manual pick, reset, undo). */
function syncLensPanel(){
  nijVerifyLensSelection();
  const prof=S.lensProfile, idx=(S.lensProfileIdx!=null?S.lensProfileIdx:-1);
  const def=S.lensDefects||{dist:true,vig:true,tca:true};
  const quickOff=document.getElementById('btnLensQuickOff');
  if(quickOff){
    const active=!!S.lensCorrect&&!!prof&&idx>=0;
    quickOff.style.display=active?'inline-flex':'none';
    quickOff.disabled=!active;
    quickOff.setAttribute('aria-hidden',String(!active));
  }
  $$('[data-lensprofile]').forEach(wrap=>{
    const makeSel=wrap.querySelector('[data-lensmake]');
    const modelSel=wrap.querySelector('[data-lensmodel]');
    const calib=wrap.querySelector('[data-lenscalib]');
    const note=wrap.querySelector('[data-lenscalibnote]');
    if(prof && idx>=0){
      const rec=LENSFUN_DB[idx];
      if(makeSel && makeSel.value!==rec.maker){ makeSel.value=rec.maker; onLensMakeChange(makeSel); }
      if(modelSel){modelSel.value=String(idx);modelSel.title=rec.maker+' '+rec.model+' · Lensfun';}
      if(calib) calib.style.display='flex';
      wrap.querySelectorAll('[data-lensdefect]').forEach(b=>{
        const k=b.dataset.lensdefect;
        const has = prof[k==='dist'?'dist':k]!=null;
        b.classList.toggle('on', !!def[k] && has);
        b.disabled=!has;
        b.style.opacity=has?'':'0.4';
      });
      wrap.querySelectorAll('[data-lensamt]').forEach(el=>{ el.value=(S.lensCorrectAmt==null?100:S.lensCorrectAmt); });
      wrap.querySelectorAll('[data-lensamtv]').forEach(el=>{ el.textContent=Math.round(S.lensCorrectAmt==null?100:S.lensCorrectAmt); });
      wrap.querySelectorAll('[data-lensactive]').forEach(el=>{el.textContent=S.lensCorrect?
        'Corrections active · finishing preview may be slower':
        'Corrections off · GPU preview remains available';});
      wrap.querySelectorAll('[data-lensapplybtn]').forEach(el=>{
        el.textContent=S.lensCorrect?'Disable corrections':'Apply when finished';
        el.setAttribute('aria-pressed',String(!!S.lensCorrect));
      });
      if(note){
        const bits=[];
        if(prof.dist) bits.push('distortion');
        if(prof.vig)  bits.push('vignetting');
        if(prof.tca)  bits.push('chromatic aberration');
        const cond=[];
        if(prof.focal!=null) cond.push(Math.round(prof.focal)+'mm');
        if(prof.aperture!=null) cond.push('ƒ/'+(+prof.aperture).toFixed(1).replace(/\.0$/,''));
        note.textContent='Upstream Lensfun · '+ (bits.length?bits.join(', '):'no supported coefficients')
          + (cond.length?(' · at '+cond.join(' ')):'') + '.';
      }
    } else {
      if(calib) calib.style.display='none';
    }
  });
}
/* Clears the manual pickers and the resolved profile back to untouched. */
function resetLensProfileUI(){
  const quickOff=document.getElementById('btnLensQuickOff');
  if(quickOff){quickOff.style.display='none';quickOff.disabled=true;quickOff.setAttribute('aria-hidden','true');}
  $$('[data-lensmake]').forEach(el=>{ el.value=''; });
  $$('[data-lensmodel]').forEach(el=>{ el.innerHTML='<option value="">Select a make first</option>'; el.disabled=true; el.value=''; });
  $$('[data-lensdetect]').forEach(el=>{ el.style.display='none'; el.innerHTML=''; });
  $$('[data-lenscalib]').forEach(el=>{ el.style.display='none'; });
}
/* Best-effort EXIF match: score every DB record against the file's LensModel
   (and camera Make as a tie-breaker for native lenses whose LensModel omits the
   brand). Requires a maker/brand hit plus either an explicit alias hit or a
   focal-range/model-token hit, so we don't mis-apply a wildly different lens.
   Returns {idx, rec} or null. */
function findLensProfileMatch(lensStr, cameraMake,shotFocal,cameraModel){
  if(!lensStr) return null;
  const norm=s=>(''+s).toLowerCase().replace(/[^a-z0-9.]+/g,'');
  const hay=norm(lensStr);
  const cam=cameraMake?norm(cameraMake):'';
  const model=cameraModel?norm(cameraModel):'';
  const camInfo=LENSFUN_FULL_DB.cameras.find(c=>{
    const cm=norm(c.model),mk=norm(c.maker);
    return !!model&&(cm===model||cm.endsWith(model))&&(!cam||mk.includes(cam)||cam.includes(mk));
  })||null;
  // Include an optional manufacturer mount suffix: A063 and A063Z are both
  // complete identifiers, not substring matches against arbitrary model text.
  const skuPattern=/\b[A-Za-z]{1,3}\d{3,5}[A-Za-z]?\b/g;
  const lensCodes=(String(lensStr).match(skuPattern)||[]).map(norm);
  let best=null, bestScore=0;
  for(let i=0;i<LENSFUN_DB.length;i++){
    const rec=LENSFUN_DB[i];
    const mountMatches=!camInfo||!rec.mount||rec.mount==='Imported'||
      norm(rec.mount).includes(norm(camInfo.mount));
    const brands=rec.maker.split(' / ');
    const brandHit=brands.some(b=>hay.includes(norm(b))) || (cam && brands.some(b=>cam.includes(norm(b))));
    // Some Sony/Nikon EXIF strings omit the third-party brand but include an
    // exact manufacturer's lens ID (e.g. Tamron A063). A bare focal-range
    // match is NEVER enough for automatic selection.
    const modelCodes=(rec.model.match(skuPattern)||[]).map(norm);
    const exactSkuHit=lensCodes.some(code=>modelCodes.includes(code));
    const range=rec.model.match(/(\d+(?:\.\d+)?)(?:-(\d+(?:\.\d+)?))?mm/i);
    const shotRange=String(lensStr).match(/(\d+(?:\.\d+)?)(?:-(\d+(?:\.\d+)?))?mm/i);
    const exactRange=!!range&&!!shotRange&&norm(range[0])===norm(shotRange[0]);
    const modelAperture=rec.model.match(/f\/?(\d+(?:\.\d+)?)/i);
    const lensAperture=String(lensStr).match(/(?:f\/?|1:)(\d+(?:\.\d+)?)/i);
    const apertureMatches=!!modelAperture&&!!lensAperture&&
      Math.abs(+modelAperture[1]-+lensAperture[1])<=0.18;
    // Lensfun currently records Tamron's Sony-E A063 optical family as A063Z.
    // Accept this *specific verified record* only with a known Sony-E camera,
    // the matching 28-75mm range and f/2.8 aperture. Don't strip arbitrary
    // suffixes (A063 vs A064 or another mount can mean a different optic).
    const knownA063Variant=rec.source==='lensfun'&&norm(rec.maker)==='tamron'&&
      lensCodes.includes('a063')&&modelCodes.includes('a063z')&&
      !!camInfo&&norm(camInfo.mount)==='sonye'&&mountMatches&&
      exactRange&&apertureMatches;
    const skuHit=exactSkuHit||knownA063Variant;
    // When the camera gives us a distinctive lens ID, a different lens with
    // a similar focal length is not a plausible fallback. This prevents the
    // Tamron A063 sample being offered a Sony A-mount 28-75mm profile.
    if(lensCodes.length&&!skuHit)continue;
    // Reject near-name matches with incompatible focal ranges or apertures.
    // A focal-length coincidence alone is not a calibrated lens identity.
    if(range&&shotRange&&!exactRange)continue;
    if(range&&Number.isFinite(+shotFocal)&&+shotFocal>0){
      const low=+range[1],high=+(range[2]||range[1]);
      if(+shotFocal<low-0.4||+shotFocal>high+0.4)continue;
    }
    if(modelAperture&&lensAperture&&Math.abs(+modelAperture[1]-+lensAperture[1])>0.18)continue;
    if(!mountMatches&&!exactRange&&!skuHit)continue;
    // Every candidate is sourced from the bundled upstream Lensfun dataset;
    // prioritize distinctive model identifiers, not focal length alone.
    let score=4;
    if(brandHit) score+=1;
    if(skuHit)score+=6;
    if(exactRange)score+=3;
    // Alias substrings are strong signals.
    const aliasHit=!!(rec.aliases&&rec.aliases.some(a=>hay.includes(norm(a))));
    if(aliasHit)score+=3;
    if(!skuHit&&!aliasHit&&!exactRange)continue;
    // A focal token from the model name appearing in the lens string.
    const fm=rec.model.match(/(\d+(?:\.\d+)?-\d+(?:\.\d+)?mm|\d+(?:\.\d+)?mm)/i);
    if(fm && hay.includes(norm(fm[1]))) score+=2;
    // An aperture token (e.g. f2.8, f1.4) shared with the model.
    const am=rec.model.match(/f\/?(\d+(?:\.\d+)?)/i);
    if(am && (hay.includes('f'+norm(am[1])) || hay.includes(norm(am[1])+''))) score+=0.5;
    // Never auto-select a generic focal-only match: require an alias or a
    // distinctive model token plus consistent aperture metadata.
    const distinctive=skuHit||aliasHit;
    if((brandHit||skuHit) && score>=3 && score>bestScore){
      bestScore=score;
      const cropMatches=!camInfo||!rec.crop||Math.abs(rec.crop/camInfo.crop-1)<0.12;
      best={idx:i,rec,score,confidence:(rec.source==='lensfun'&&distinctive&&score>=8&&cropMatches&&mountMatches)?'high':'review'};
    }
  }
  return best;
}
/* Select a verified EXIF match without altering pixels on import; only an
   explicit user action enables its correction. */
function applyDetectedLensProfile(idx, silent, enable=true){
  const rec=LENSFUN_DB[idx]; if(!rec) return;
  const ex=(typeof S!=='undefined')?S.exif:null;
  const focal=ex&&ex.focalV!=null?ex.focalV:(ex&&ex.focal!=null?ex.focal:null);
  const aperture=ex&&ex.aperture!=null?ex.aperture:null;
  S.lensProfile=resolveLensProfile(rec,focal,aperture);
  S.lensProfileIdx=idx;
  S.lensCorrect=!!enable;
  if(S.lensCorrectAmt==null) S.lensCorrectAmt=100;
  if(!S.lensDefects) S.lensDefects={dist:true,vig:true,tca:true};
  syncLensPanel();
  if(enable){render();commit();}
  if(typeof toast==='function' && !silent) toast((enable?'Lens correction applied: ':'Lens profile ready: ')+rec.maker+' '+rec.model);
}
/* Preselect a high-confidence EXIF LensModel match, with corrections OFF.
   Never override a manual selection or a restored project's enabled state. */
function renderLensDetect(){
  const ex=(typeof S!=='undefined')?S.exif:null;
  const shotFocal=ex&&(ex.focalV!=null?ex.focalV:ex.focal);
  const match=(ex && ex.lens)?findLensProfileMatch(ex.lens,ex.make,shotFocal,ex.model):null;

  if(match&&match.confidence==='high' && !S.lensAutoApplied && S.lensProfile==null){
    S.lensAutoApplied=true;
    applyDetectedLensProfile(match.idx,true,false);
    if(typeof toast==='function')toast('Verified lens identified: '+match.rec.maker+' '+match.rec.model+'. Corrections stay off until you apply them after editing.');
  }
  // No speculative lens-family correction is offered or applied.
  syncLensPanel();
  $$('[data-lensdetect]').forEach(host=>{
    if(match){
      host.style.display='';
      host.innerHTML='EXIF candidate ('+(match.confidence==='high'?'high-confidence Lensfun-sourced match':'needs review')+'): <b>'+esc(match.rec.maker+' '+match.rec.model)+'</b>'
        +(S.lensProfileIdx===match.idx?
          '<span style="display:block;margin-top:5px">'+(S.lensCorrect?'Corrections enabled.':'Selected but inactive. Use “Apply when finished” above.')+'</span>':
          '<button class="tl" style="width:100%;margin-top:6px" onclick="applyDetectedLensProfile('+match.idx+')">Apply this verified profile when finished</button>');
    } else if(ex && ex.lens){
      host.style.display='';
      host.innerHTML='EXIF lens <b>'+esc(ex.lens)+'</b> has no confident calibrated match — '
        +'pick a model above, or adjust the manual sliders. Nothing was applied automatically.';
    } else {
      host.style.display='none'; host.innerHTML='';
    }
  });
}
