    +sec('Render consistency','<p class="hint" style="margin:0 0 8px;font-size:.72rem">Compare 8/16-bit tone results and, when a native RAW is active, its float preview and 16-bit output maths. GPU preview also runs an automatic CPU comparison.</p><button class="tl" style="width:100%" onclick="nijRunRenderParity()">Check rendering consistency</button>',false)
    +sec('Crop &amp; Rotate',sliderRow('rotate','Rotate',-180,180,0.5)+'<button class="tl" onclick="cropFreeRotate()" style="width:100%;margin:-4px 0 8px;display:flex;align-items:center;justify-content:center;gap:6px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:14px;height:14px"><path d="M6 2v14a2 2 0 0 0 2 2h14"/><path d="M2 6h14a2 2 0 0 1 2 2v14"/></svg>Bake &amp; auto-crop</button>'+sliderRow('straighten','Straighten',-45,45,0.1)+'<div class="tools"><button class="tl" onclick="flipH()">Flip H</button><button class="tl" onclick="flipV()">Flip V</button><button class="tl" onclick="rot90()">90°</button></div><p class="note" style="margin-top:8px">Use the <b>Crop</b> tool in the top bar to set a crop region.</p>',false);
