      +'<button class="nij-auto-subject" type="button" data-nij-auto-subject onclick="nijDetectWithProfile()" aria-label="Auto select subject"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="7"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg>Auto select</button>'
