    // frame as background rather than dividing by zero.
    if(subjectRect&&outside.n<8){
      outside.n=outside.y=outside.r=outside.g=outside.b=outside.s=outside.grad=0;
      for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){
        const nx=(x+.5)/w,ny=(y+.5)/h;
        if(nx>=rx0&&nx<=rx1&&ny>=ry0&&ny<=ry1)continue;
        const k=y*w+x;addPx(outside,k,Math.hypot((sm[k+1]-sm[k-1])*.5,(sm[k+w]-sm[k-w])*.5));
      }
    }
    const total=cells.reduce((a,b)=>a+b,0),fractions=Array.from(cells,v=>total>1e-9?v/total:0);
    const entropy=total>1e-9?-fractions.reduce((sum,p)=>p>0?sum+p*Math.log(p):sum,0)/Math.log(9):0;
