  nijTapCount=0;nijSelectionKind='subject';
  if(!S.proxy){ toast('Open a photo first'); return; }
  // Clear any brush/region so detection runs fully automatically.
  if(S.brushMask) S.brushMask.fill(0);
  S.brushOn=false; const st=$('#stage'); if(st)st.classList.remove('brushing');
  if(typeof updateBrushUI==='function')updateBrushUI();
  S.region=null; if(typeof updateRegionUI==='function')updateRegionUI();
  S.focusPts=[]; updateFocusUI();
