  // to forget. (Other stage tools are switched off so they don't grab the pointer.)
  if(!S.retouchOn && S.proxy){
    S.retouchOn=true;
    const stg=$('#stage'); if(stg) stg.classList.add('retouching');
    S.brushOn=false; S.maskEraseOn=false;
    if(typeof updateBrushUI==='function')updateBrushUI();
    if(typeof updateMaskEraseUI==='function')updateMaskEraseUI();
    if(stg){stg.classList.remove('brushing');stg.classList.remove('merase');}
  }
