  S.retouchOn=!S.retouchOn;
  const stg=$('#stage'); if(stg) stg.classList.toggle('retouching',S.retouchOn);
  // Ensure other stage tools are off so they don't fight for the pointer.
  if(S.retouchOn){ S.brushOn=false; S.maskEraseOn=false; if(typeof updateBrushUI==='function')updateBrushUI(); if(typeof updateMaskEraseUI==='function')updateMaskEraseUI(); if(stg){stg.classList.remove('brushing');stg.classList.remove('merase');} }
