  $$('[data-rtbtn]').forEach(b=>{ b.textContent=on?'Retouch off':'Retouch on'; b.classList.toggle('on',on); });
  $$('[data-rtsizerow]').forEach(r=>r.style.display=on?'flex':'none');
  $$('[data-rtundo]').forEach(b=>b.style.display=(S.retouch&&S.retouch.length)?'':'none');
  $$('[data-rtclear]').forEach(b=>b.style.display=(S.retouch&&S.retouch.length)?'':'none');
