  v=Number(v);
  if(!Number.isFinite(v)) v=Number(DEF[k])||0;
  if((k==='perspV'||k==='perspH')&&S.perspectiveQuad){S.perspectiveQuad=null;nijMarkCornerMode();}
  P[k]=v;
