  let retouchProxy=null,retouchSource=null,retouchW=0,retouchH=0;
  let active=false,validatedKey='',validatedGeometryKey='',errorMessage='',detailFailed=false,detailError='',maskFailed=false,maskError='',geometryFailed=false,geometryError='',useDetail=false,useMask=false,useGeometry=false;
