    // values, not the program, so resolve each location only once per context.
    // The optional direct-detail and masked programs use separate locations.
    const key=(useGeometry?'geo:'+(useMask?'mask:':useDetail?'detail:':'base:'):
      useMask?'mask:':useDetail?'detail:':'base:')+name;
    if(!uniformLocations.has(key))uniformLocations.set(key,gl.getUniformLocation(useGeometry?geometryProgram:useMask?maskProgram:useDetail?detailProgram:program,name));
    return uniformLocations.get(key);
