  tag(256,4,1,w);tag(257,4,1,h);tag(258,3,3,bitsOffset);
  tag(259,3,1,1);tag(262,3,1,2);tag(273,4,1,pixelsOffset);
  tag(277,3,1,3);tag(278,4,1,h);tag(279,4,1,w*h*12);
