          iso: meta.iso ? Math.round(meta.iso) : undefined,
          exposure: meta.shutter ? (meta.shutter < 1 ? '1/' + Math.round(1 / meta.shutter) + ' s' : meta.shutter.toFixed(1) + ' s') : undefined,
          fnum: meta.aperture ? Math.round(meta.aperture * 10) / 10 : undefined,
