    // proxy cell. Exact uint32 summation uses half the temporary memory of
    // Float64 without changing any pixel averages. Retain Float64 for unusual
    // gigantic ratios where a 32-bit sample sum might overflow.
    const maxSamples=(Math.ceil(m.w/pw)+1)*(Math.ceil(m.h/ph)+1);
    const exact32=maxSamples<=Math.floor(4294967295/65535);
    const acc=exact32?new Uint32Array(pw*ph*3):new Float64Array(pw*ph*3);
