          worker.onmessage=e=>{clearTimeout(timer);const m=e.data||{};m.error?reject(new Error(m.error)):resolve(new Uint16Array(m.buffer));};
          worker.onerror=e=>{clearTimeout(timer);reject(new Error(e.message||'denoise worker error'));};
